# filename: parse_layout.py

def extract_house_positions(file_path):
    with open(file_path, 'r') as f:
        lines = [line.rstrip('\n') for line in f]

    # Identify the road line as the first line containing '-'
    road_idx = None
    for i, line in enumerate(lines):
        if '-' in line:
            road_idx = i
            break
    if road_idx is None:
        raise ValueError('No road line found.')

    positions = set()
    for neighbor in (road_idx - 1, road_idx + 1):
        if 0 <= neighbor < len(lines):
            for pos, ch in enumerate(lines[neighbor]):
                if ch == 'H':
                    positions.add(pos)

    return sorted(positions)

